// auth-security · кейсы auth-01, auth-02, auth-04 (.qa/tests/auth-security/)
import { test, expect } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

test.describe('auth-security — נחיתה לפי תפקיד וסשן', () => {
  test.describe('מפיץ', () => {
    test.use({ storageState: auth('admin') });

    test('מפיץ נוחת ב-/catalog, נשאר מחובר אחרי רענון, כתובת לא מוכרת → /catalog #6a38cf59 #6a6f302c #6a672659 @desktop @prod-safe', async ({ page }) => {
      await page.goto('/');
      await expect(page).toHaveURL(/\/catalog/);
      await expect(page.getByText('קטלוג וניהול').first()).toBeVisible();
      await expect(page.getByText('צוות והרשאות').first()).toBeVisible();

      await page.reload();
      await expect(page).toHaveURL(/\/catalog/);
      await expect(page).not.toHaveURL(/\/login/);

      await page.goto('/definitely-not-a-route');
      await expect(page).toHaveURL(/\/catalog/);
      await expect(page.getByText('שגיאה 403')).toHaveCount(0);
    });
  });

  test.describe('לקוח', () => {
    test.use({ storageState: auth('buyer') });

    test('לקוח נוחת ב-/shop, כתובת לא מוכרת → /shop בלי 403 #6a672659 #6a38cf59 #6a6f302c @prod-safe', async ({ page }) => {
      await page.goto('/');
      await expect(page).toHaveURL(/\/shop/);
      await expect(page.getByText('שלום,').first()).toBeVisible();

      await page.goto('/definitely-not-a-route');
      await expect(page).toHaveURL(/\/shop/);
      await expect(page.getByText('הגישה נחסמה')).toHaveCount(0);
      await expect(page.getByText('שגיאה 403')).toHaveCount(0);

      await page.reload();
      await expect(page).toHaveURL(/\/shop/);
      await expect(page).not.toHaveURL(/\/login/);
    });
  });

  test.describe('אורח', () => {
    for (const route of ['/catalog', '/shop', '/team', '/shop/orders']) {
      test(`אורח ב-${route} מופנה להתחברות בעברית RTL #6a38cf59 @prod-safe`, async ({ page }) => {
        await page.goto(route);
        await expect(page).toHaveURL(/\/login/);
        await expect(page.locator('html')).toHaveAttribute('dir', 'rtl');
        await expect(page.locator('html')).toHaveAttribute('lang', 'he');
        await expect(page.getByRole('heading', { name: 'התחברות' })).toBeVisible();
        await expect(page.getByRole('textbox', { name: 'אימייל' })).toBeVisible();
        await expect(page.getByRole('textbox', { name: 'סיסמה' })).toBeVisible();
        await expect(page.getByRole('button', { name: 'כניסה', exact: true })).toBeVisible();
      });
    }
  });
});
